// Sources, in order:
//   webhook  → body of "Inbound Lead Webhook" (shared-token check outside sandbox)
//   sandbox  → embedded fixture (= sample-payloads/queued-leads.json)
//   queue    → response of "Queue: Fetch Pending Leads"
// Validates lead_id, drops do-not-contact leads, de-duplicates, caps the batch
// and, in production executions, skips leads dispatched within DEDUPE_HOURS.
//
// Security note: WEBHOOK_SHARED_TOKEN is read here only because n8n's built-in
// webhook header auth needs a stored credential. The value never leaves this
// node and is compared in constant time.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const FIXTURE = {
