const fromWebhook = $('Inbound Lead Webhook').isExecuted;

let raw = [];
let source;
let auth = 'not_applicable';
if (fromWebhook) {
  source = 'webhook';
  const req = $('Inbound Lead Webhook').first().json;
  if (!cfg.sandboxMode && cfg.requireWebhookToken) {
    let crypto;
    try { crypto = require('crypto'); } catch (e) { throw new Error('Webhook token check needs NODE_FUNCTION_ALLOW_BUILTIN=crypto.'); }
    let expected = '';
    try { expected = String($env.WEBHOOK_SHARED_TOKEN || ''); } catch (e) { expected = ''; }
    if (!expected) throw new Error('Rejected: WEBHOOK_SHARED_TOKEN is not set and REQUIRE_WEBHOOK_TOKEN is not false.');
    const h = Object.fromEntries(Object.entries(req.headers || {}).map(([k, v]) => [k.toLowerCase(), String(v)]));
    const got = (h.authorization || '').replace(/^Bearer\s+/i, '') || h['x-webhook-token'] || '';
    const a = crypto.createHash('sha256').update(got).digest();
    const b = crypto.createHash('sha256').update(expected).digest();
    if (!got || !crypto.timingSafeEqual(a, b)) throw new Error('Rejected: missing or invalid webhook token.');
    auth = 'verified';
  } else auth = cfg.sandboxMode ? 'skipped (sandbox)' : 'disabled (REQUIRE_WEBHOOK_TOKEN=false)';
  const body = req.body;
  raw = Array.isArray(body) ? body : Array.isArray(body?.leads) ? body.leads : (body && typeof body === 'object' ? [body] : []);
} else if (cfg.sandboxMode) {
  source = 'fixture';
  raw = FIXTURE.leads;
} else {
  source = 'queue';
  const resp = $('Queue: Fetch Pending Leads').all().map((i) => i.json);
  if (resp.length === 1 && resp[0].error) throw new Error(`Queue read failed: ${JSON.stringify(resp[0].error).slice(0, 200)}`);
  raw = resp.flatMap((j) => (Array.isArray(j.leads) ? j.leads : Array.isArray(j.data) ? j.data : (j.lead_id || j.id ? [j] : [])));
}

let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const persist = Boolean(store) && !cfg.sandboxMode && cfg.executionMode === 'production';
const recent = persist ? (store.dispatched || {}) : {};
if (persist) for (const [k, t] of Object.entries(recent)) if (Date.now() - t > cfg.dedupeHours * 3600000) delete recent[k];

const s = (v, n = 200) => (v === undefined || v === null ? null : String(v).trim().slice(0, n) || null);
const seen = new Set();
const leads = [];
const rejected = [];
for (const r of raw) {
  const leadId = s(r?.lead_id ?? r?.id, 100);
  if (!leadId) { rejected.push({ leadId: null, reason: 'missing_lead_id' }); continue; }
  if (seen.has(leadId)) { rejected.push({ leadId, reason: 'duplicate_in_batch' }); continue; }
  seen.add(leadId);
  if (r.do_not_contact === true || String(r.do_not_contact).toLowerCase() === 'true') { rejected.push({ leadId, reason: 'do_not_contact' }); continue; }
  if (recent[leadId]) { rejected.push({ leadId, reason: 'recently_dispatched' }); continue; }
  if (!s(r.email) && !s(r.phone)) { rejected.push({ leadId, reason: 'no_contact_point' }); continue; }
  if (leads.length >= cfg.maxLeadsPerRun) { rejected.push({ leadId, reason: 'over_max_leads_per_run' }); continue; }
  leads.push({
    leadId,
    email: s(r.email)?.toLowerCase() || null,
    phone: s(r.phone, 40),
    timezone: s(r.timezone ?? r.time_zone ?? r.tz, 64),
    country: s(r.country ?? r.country_code, 3)?.toUpperCase() || null,
    region: s(r.region ?? r.state, 40)?.toUpperCase() || null,
    channel: s(r.channel, 20)?.toLowerCase() || 'email',
    scheduledDispatchAt: s(r.scheduled_dispatch_at, 40),
    payload: r.payload && typeof r.payload === 'object' ? r.payload : {},
  });
}
return [{ json: { source, auth, received: raw.length, count: leads.length, leads, rejected } }];

// ─────────────────────────────────────────────────────────────────────────────
// Timezone Resolution & Business-Hours Evaluation
// Resolution hierarchy (first hit wins), with confidence:
//   1. explicit IANA field (timezone / time_zone / tz), validated by Intl  high
//   2. phone: NANP area code (+1), or a single-zone country calling code,
//      or an Australian / Brazilian / Mexican area prefix                  high/medium
//   3. country (+ region/state for US, CA, AU, BR, MX) fields              medium
//   4. email domain ccTLD (generic TLDs such as .com are skipped)           low
//   5. FALLBACK_TIMEZONE (FALLBACK_POLICY=use_fallback) or hold             fallback
// Then computes the recipient's local time and weekday, decides whether the
// lead is inside the business window now, and otherwise the exact next valid
// scheduled_dispatch_at (UTC ISO), DST-safe, honouring weekend days, regional
// Fri–Sat weekends, holidays and an optional deterministic spread.
// Uses only the built-in Intl API; no packages.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { leads } = $input.first().json;
if (!(cfg.startMinutes < cfg.endMinutes - cfg.endBufferMinutes)) throw new Error(`Invalid business window ${cfg.businessStart}–${cfg.businessEnd} (END_BUFFER_MINUTES=${cfg.endBufferMinutes}). BUSINESS_START_HOUR must be earlier than BUSINESS_END_HOUR.`);
// EVALUATION_TIME_OVERRIDE is honoured only in sandbox or dry run (see Config).
const NOW = cfg.nowOverride && Number.isFinite(Date.parse(cfg.nowOverride)) ? Date.parse(cfg.nowOverride) : Date.now();

// ── Reference tables ──
const NANP_BY_ZONE = {
