  be: 'Europe/Brussels', ch: 'Europe/Zurich', at: 'Europe/Vienna', dk: 'Europe/Copenhagen', se: 'Europe/Stockholm', no: 'Europe/Oslo', fi: 'Europe/Helsinki',
  pl: 'Europe/Warsaw', pt: 'Europe/Lisbon', gr: 'Europe/Athens', cz: 'Europe/Prague', hu: 'Europe/Budapest', ro: 'Europe/Bucharest', il: 'Asia/Jerusalem',
  ae: 'Asia/Dubai', sa: 'Asia/Riyadh', in: 'Asia/Kolkata', pk: 'Asia/Karachi', bd: 'Asia/Dhaka', sg: 'Asia/Singapore', hk: 'Asia/Hong_Kong', jp: 'Asia/Tokyo',
  kr: 'Asia/Seoul', cn: 'Asia/Shanghai', tw: 'Asia/Taipei', ph: 'Asia/Manila', th: 'Asia/Bangkok', vn: 'Asia/Ho_Chi_Minh', my: 'Asia/Kuala_Lumpur',
  nz: 'Pacific/Auckland', za: 'Africa/Johannesburg', ng: 'Africa/Lagos', ke: 'Africa/Nairobi', eg: 'Africa/Cairo', cl: 'America/Santiago',
  ar: 'America/Argentina/Buenos_Aires', pe: 'America/Lima',
  // multi-zone countries: most populous zone, low confidence
  au: 'Australia/Sydney', ca: 'America/Toronto', br: 'America/Sao_Paulo', mx: 'America/Mexico_City',
};
// Countries whose business week is Sunday–Thursday (weekend Friday–Saturday).
const FRI_SAT = new Set(['Asia/Jerusalem', 'Asia/Riyadh', 'Asia/Qatar', 'Asia/Kuwait', 'Asia/Bahrain', 'Asia/Muscat', 'Africa/Cairo']);

// ── Helpers ──
const valid = (tz) => { if (!tz) return false; try { new Intl.DateTimeFormat('en-US', { timeZone: tz }).format(0); return true; } catch (e) { return false; } };
const fmtCache = {};
const parts = (ms, tz) => {
  const f = fmtCache[tz] || (fmtCache[tz] = new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', weekday: 'short' }));
  const o = {};
  for (const p of f.formatToParts(new Date(ms))) o[p.type] = p.value;
  return { y: +o.year, m: +o.month, d: +o.day, h: +o.hour % 24, mi: +o.minute, s: +o.second, wd: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(o.weekday) };
};
const offsetMs = (ms, tz) => { const p = parts(ms, tz); return Date.UTC(p.y, p.m - 1, p.d, p.h, p.mi, p.s) - Math.floor(ms / 1000) * 1000; };
// Wall-clock time in tz → UTC ms (two-pass, correct across DST changes).
const zonedToUtc = (y, m, d, h, mi, tz) => {
  const guess = Date.UTC(y, m - 1, d, h, mi);
  let t = guess - offsetMs(guess, tz);
  const o2 = offsetMs(t, tz);
  t = guess - o2;
  return t;
};
const fmtOffset = (ms, tz) => { const o = Math.round(offsetMs(ms, tz) / 60000); const s = o < 0 ? '-' : '+'; const a = Math.abs(o); return `${s}${String(Math.floor(a / 60)).padStart(2, '0')}:${String(a % 60).padStart(2, '0')}`; };
const localIso = (ms, tz) => { const p = parts(ms, tz); const pad = (n) => String(n).padStart(2, '0'); return `${p.y}-${pad(p.m)}-${pad(p.d)}T${pad(p.h)}:${pad(p.mi)}:${pad(p.s)}${fmtOffset(ms, tz)}`; };
const hash = (s) => { let h = 2166136261; for (const ch of String(s)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
const DAY = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

function resolve(l) {
  const tried = [];
  if (l.timezone) {
    if (valid(l.timezone)) return { tz: l.timezone, method: 'explicit_iana', confidence: 'high', tried };
    tried.push(`explicit_iana_invalid:${l.timezone}`);
  }
  if (l.phone) {
    let digits = String(l.phone).replace(/[^\d+]/g, '');
    if (digits.startsWith('00')) digits = `+${digits.slice(2)}`;
    if (digits.startsWith('+')) {
      const n = digits.slice(1);
      if (n.startsWith('1') && n.length === 11) {
        const ac = n.slice(1, 4);
        if (NANP[ac]) return { tz: NANP[ac], method: `phone_nanp_area_code:${ac}`, confidence: 'high', tried };
        tried.push(`phone_nanp_unknown_area_code:${ac}`);
      } else if (n.startsWith('61')) {
        const a = n.slice(2, 3);
        const z = { 2: 'Australia/Sydney', 3: 'Australia/Melbourne', 7: 'Australia/Brisbane' }[a];
        if (z) return { tz: z, method: `phone_au_area:${a}`, confidence: 'medium', tried };
        tried.push(`phone_au_ambiguous:${a === '4' ? 'mobile' : a}`);
      } else if (n.startsWith('55')) {
        const a = Number(n.slice(2, 3));
        if (a >= 1 && a <= 5) return { tz: 'America/Sao_Paulo', method: `phone_br_area:${n.slice(2, 4)}`, confidence: 'medium', tried };
        tried.push('phone_br_ambiguous');
      } else if (n.startsWith('52')) {
        return { tz: 'America/Mexico_City', method: 'phone_mx_default', confidence: 'medium', tried };
      } else {
        const cc = [3, 2, 1].map((k) => n.slice(0, k)).find((k) => CC[k]);
        if (cc) return { tz: CC[cc], method: `phone_country_code:+${cc}`, confidence: 'high', tried };
        tried.push(`phone_country_unmapped:+${n.slice(0, 3)}`);
      }
    } else tried.push('phone_not_e164');
  }
  if (l.country) {
    const reg = REGION[l.country];
    if (reg && l.region) {
      for (const [z, list] of Object.entries(reg)) if (list.split(' ').includes(l.region)) return { tz: z, method: `country_region:${l.country}-${l.region}`, confidence: 'medium', tried };
      tried.push(`region_unmapped:${l.country}-${l.region}`);
    } else if (reg) tried.push(`country_multi_zone_without_region:${l.country}`);
    else if (ISO[l.country]) return { tz: ISO[l.country], method: `country:${l.country}`, confidence: 'medium', tried };
    else tried.push(`country_unmapped:${l.country}`);
  }
  if (l.email && l.email.includes('@')) {
    const tld = l.email.split('@')[1].split('.').pop();
    if (TLD[tld]) return { tz: TLD[tld], method: `email_cctld:.${tld}`, confidence: 'low', tried };
    tried.push(`email_tld_generic:.${tld}`);
  }
  return { tz: null, method: 'unresolved', confidence: 'none', tried };
}

function weekendFor(tz) { return cfg.regionalWeekends && FRI_SAT.has(tz) ? new Set([5, 6]) : new Set(cfg.weekendDays); }
function isBusinessDay(p, tz) {
  if (cfg.skipWeekends && weekendFor(tz).has(p.wd)) return false;
  const key = `${p.y}-${String(p.m).padStart(2, '0')}-${String(p.d).padStart(2, '0')}`;
  return !cfg.holidays.includes(key);
}
const endMin = () => cfg.endMinutes - cfg.endBufferMinutes;

function evaluate(tz, leadId) {
  const p = parts(NOW, tz);
  const nowMin = p.h * 60 + p.mi;
  const local = { localTime: localIso(NOW, tz), weekday: DAY[p.wd], utcOffset: fmtOffset(NOW, tz) };
  if (isBusinessDay(p, tz) && nowMin >= cfg.startMinutes && nowMin < endMin()) return { inWindow: true, ...local, scheduledDispatchAt: new Date(NOW).toISOString(), reason: 'inside_business_hours' };
  // Next valid slot: today if before the window on a business day, else the next business day.
  let why = !isBusinessDay(p, tz) ? (cfg.holidays.includes(`${p.y}-${String(p.m).padStart(2, '0')}-${String(p.d).padStart(2, '0')}`) ? 'holiday' : 'weekend') : nowMin < cfg.startMinutes ? 'before_business_hours' : 'after_business_hours';
  const spread = cfg.spreadMinutes > 0 ? hash(leadId) % Math.max(1, Math.min(cfg.spreadMinutes, endMin() - cfg.startMinutes)) : 0;
  for (let add = 0; add <= 14; add += 1) {
    // Date arithmetic on the local calendar date (UTC used as a neutral calendar).
    const cal = new Date(Date.UTC(p.y, p.m - 1, p.d + add));
    const y = cal.getUTCFullYear(); const m = cal.getUTCMonth() + 1; const d = cal.getUTCDate();
    const startMs = zonedToUtc(y, m, d, Math.floor(cfg.startMinutes / 60), cfg.startMinutes % 60, tz) + spread * 60000;
    if (startMs <= NOW) continue;
    const q = parts(startMs, tz);
    if (!isBusinessDay(q, tz)) continue;
    return { inWindow: false, ...local, scheduledDispatchAt: new Date(startMs).toISOString(), scheduledLocal: localIso(startMs, tz), waitMinutes: Math.round((startMs - NOW) / 60000), reason: why };
  }
  return { inWindow: false, ...local, scheduledDispatchAt: null, reason: 'no_business_day_within_14_days' };
}

const evaluated = leads.map((l) => {
  const r = resolve(l);
  let tz = r.tz; let method = r.method; let confidence = r.confidence;
  if (!tz) {
    if (cfg.fallbackPolicy === 'hold' || !valid(cfg.fallbackTimezone)) {
      return { ...l, resolvedTimezone: null, resolution: { method, confidence, tried: r.tried }, decision: 'hold', reason: 'timezone_unresolved', scheduledDispatchAt: null };
    }
    tz = cfg.fallbackTimezone; method = 'fallback_timezone'; confidence = 'fallback';
  }
  const e = evaluate(tz, l.leadId);
  return {
    ...l,
    resolvedTimezone: tz,
    resolution: { method, confidence, tried: r.tried },
    ...e,
    decision: e.inWindow ? 'dispatch_now' : e.scheduledDispatchAt ? 'defer' : 'hold',
  };
});
const counts = { leads: evaluated.length, dispatch_now: 0, defer: 0, hold: 0 };
for (const x of evaluated) counts[x.decision] += 1;
return [{ json: { evaluatedAt: new Date(NOW).toISOString(), window: { start: cfg.businessStart, end: cfg.businessEnd, endBufferMinutes: cfg.endBufferMinutes, skipWeekends: cfg.skipWeekends }, counts, leads: evaluated } }];

// ─────────────────────────────────────────────────────────────────────────────
// Route & Build Dispatch Batches
// Splits evaluated leads into:
//   dispatch_now → batches of DISPATCH_BATCH_SIZE for the dispatch webhook
//   defer        → queue update with scheduled_dispatch_at
//   hold         → queue update with status "needs_timezone" (no dispatch)
// Only lead_id, contact points, channel, timezone data and the lead's own
// payload object are forwarded to the sequencer.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ev = $input.first().json;
const now = ev.leads.filter((l) => l.decision === 'dispatch_now');
const batches = [];
for (let i = 0; i < now.length; i += cfg.dispatchBatchSize) {
  const slice = now.slice(i, i + cfg.dispatchBatchSize);
  batches.push({
    batchId: `${cfg.runId}-${batches.length + 1}`,
    leadIds: slice.map((l) => l.leadId),
    body: {
      batch_id: `${cfg.runId}-${batches.length + 1}`,
      generated_at: ev.evaluatedAt,
      leads: slice.map((l) => ({
        lead_id: l.leadId, email: l.email, phone: l.phone, channel: l.channel,
        timezone: l.resolvedTimezone, timezone_method: l.resolution.method, timezone_confidence: l.resolution.confidence,
        local_time: l.localTime, dispatch_at: l.scheduledDispatchAt, payload: l.payload,
      })),
    },
  });
}
const dispatchAllowed = !cfg.sandboxMode && !cfg.dryRun && cfg.dispatchEnabled;
return [{ json: { ...ev, batches, dispatchAllowed, dispatchCount: now.length } }];

// ─────────────────────────────────────────────────────────────────────────────
// Collect Dispatch Results
// Joins batch responses by index. A lead counts as dispatched only when its
// batch call succeeded. Successful lead_ids are remembered for DEDUPE_HOURS
// (production executions) so a failed queue update can't cause a re-send.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const batches = $('Emit Dispatch Batches').all();
const resp = $input.all();
if (resp.length !== batches.length) throw new Error(`Dispatch result mismatch: ${batches.length} batches vs ${resp.length} responses. Unpin "Dispatch: Send Batch" or align its items.`);
const failedResp = (j) => Boolean(j.error) || j.ok === false || j.success === false;
const results = batches.map((b, i) => ({ batchId: b.json.batchId, leads: b.json.leadIds.length, ok: !failedResp(resp[i].json), error: failedResp(resp[i].json) ? String(resp[i].json.error?.message || resp[i].json.error || 'dispatch_failed').slice(0, 200) : null }));
const dispatched = batches.flatMap((b, i) => (results[i].ok ? b.json.leadIds : []));
const failed = batches.flatMap((b, i) => (results[i].ok ? [] : b.json.leadIds));
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
if (store && !cfg.sandboxMode && cfg.executionMode === 'production') {
  store.dispatched = store.dispatched || {};
  for (const id of dispatched) store.dispatched[id] = Date.now();
}
return [{ json: { results, dispatched, failed } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Queue Updates
// One status record per lead for the queue / CRM:
//   dispatched      → dispatched_at
//   scheduled       → scheduled_dispatch_at (+ local time, timezone)
//   needs_timezone  → held, no dispatch
//   dispatch_failed → left due, retried next run
//   ready           → inside the window but dispatch disabled / dry run
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const route = $('Route & Build Dispatch Batches').first().json;
let disp = null;
try { disp = $('Collect Dispatch Results').isExecuted ? $('Collect Dispatch Results').first().json : null; } catch (e) { disp = null; }
const ok = new Set(disp ? disp.dispatched : []);
const bad = new Set(disp ? disp.failed : []);
const updates = route.leads.map((l) => {
  const base = { lead_id: l.leadId, timezone: l.resolvedTimezone, timezone_method: l.resolution.method, timezone_confidence: l.resolution.confidence, evaluated_at: route.evaluatedAt };
  if (l.decision === 'dispatch_now') {
    if (ok.has(l.leadId)) return { ...base, status: 'dispatched', dispatched_at: new Date().toISOString() };
    if (bad.has(l.leadId)) return { ...base, status: 'dispatch_failed', scheduled_dispatch_at: l.scheduledDispatchAt };
    return { ...base, status: 'ready', scheduled_dispatch_at: l.scheduledDispatchAt };
  }
  if (l.decision === 'defer') return { ...base, status: 'scheduled', scheduled_dispatch_at: l.scheduledDispatchAt, scheduled_local_time: l.scheduledLocal, defer_reason: l.reason };
  return { ...base, status: 'needs_timezone', scheduled_dispatch_at: null, hold_reason: l.reason };
});
const queueWriteAllowed = cfg.queueWriteEnabled && updates.length > 0;
return [{ json: { updates, queueWriteAllowed, statusCounts: updates.reduce((a, u) => ({ ...a, [u.status]: (a[u.status] || 0) + 1 }), {}) } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Notification
// Slack summary + webhook JSON: dispatched vs. queued vs. held, next scheduled
// slots, failures. Lead IDs and timezones only; no emails or phone numbers.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const route = $('Route & Build Dispatch Batches').first().json;
const q = $('Build Queue Updates').first().json;
const load = $('Load & Normalize Leads').first().json;
let disp = null;
try { disp = $('Collect Dispatch Results').isExecuted ? $('Collect Dispatch Results').first().json : null; } catch (e) { disp = null; }
let qw = null;
try { qw = $('Queue: Update Lead Status').isExecuted ? $('Queue: Update Lead Status').all().map((i) => i.json) : null; } catch (e) { qw = null; }
const queueFailed = Boolean(qw && qw.some((x) => x.error));
const mode = cfg.sandboxMode ? 'SANDBOX (synthetic leads, nothing sent)' : cfg.dryRun ? 'DRY RUN (nothing dispatched)' : !cfg.dispatchEnabled ? 'DISPATCH DISABLED (nothing dispatched)' : 'LIVE';
const sc = q.statusCounts;
const deferred = route.leads.filter((l) => l.decision === 'defer').sort((a, b) => a.scheduledDispatchAt.localeCompare(b.scheduledDispatchAt));
const held = route.leads.filter((l) => l.decision === 'hold');
const byTz = {};
for (const l of route.leads) if (l.resolvedTimezone) byTz[l.resolvedTimezone] = (byTz[l.resolvedTimezone] || 0) + 1;

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Outbound dispatch scheduler', emoji: true } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `*${mode}* · window ${cfg.businessStart}–${cfg.businessEnd} local · weekends ${cfg.skipWeekends ? 'skipped' : 'allowed'} · source \`${load.source}\`` }] },
  { type: 'section', text: { type: 'mrkdwn', text: `🚀 *${sc.dispatched || 0}* dispatched · ✅ *${sc.ready || 0}* ready (not sent) · 🕒 *${sc.scheduled || 0}* queued · ⏸️ *${sc.needs_timezone || 0}* held · ❌ *${sc.dispatch_failed || 0}* failed · ${load.rejected.length} rejected` } },
];
if (deferred.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Next slots*\n${deferred.slice(0, 10).map((l) => `• \`${l.leadId}\` → ${l.scheduledLocal} (${l.resolvedTimezone}, ${l.reason})`).join('\n')}${deferred.length > 10 ? `\n…and ${deferred.length - 10} more` : ''}`.slice(0, 2900) } });
if (held.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `⏸️ *Held, timezone unresolved:* ${held.slice(0, 15).map((l) => `\`${l.leadId}\``).join(', ')}` } });
if (disp && disp.failed.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `❌ *Dispatch failed for* ${disp.failed.length} lead(s): ${disp.results.filter((r) => !r.ok).map((r) => `${r.batchId} (${r.error})`).join('; ')}`.slice(0, 2900) } });
if (queueFailed) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '⚠️ *Queue status update failed.* Dispatched leads are protected from re-sending for DEDUPE_HOURS; fix the queue endpoint before then.' } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `By timezone: ${Object.entries(byTz).map(([k, v]) => `${k} ${v}`).join(' · ') || '—'} · run ${cfg.runId}`.slice(0, 2900) }] });

const worthNotifying = (sc.dispatched || 0) > 0 || (sc.dispatch_failed || 0) > 0 || held.length > 0 || queueFailed || cfg.notifyOnEveryRun;
return [{ json: {
  worthNotifying, queueFailed,
  slackBody: { text: `Dispatch scheduler: ${sc.dispatched || 0} dispatched, ${sc.scheduled || 0} queued, ${sc.needs_timezone || 0} held (${mode}).`, blocks },
  webhookBody: { event: 'outbound.dispatch_scheduler.run', runId: cfg.runId, generatedAt: new Date().toISOString(), mode: cfg.sandboxMode ? 'sandbox' : route.dispatchAllowed ? 'live' : 'dry_run',
    window: route.window, statusCounts: sc, rejected: load.rejected.length,
    leads: q.updates.map((u) => ({ lead_id: u.lead_id, status: u.status, timezone: u.timezone, timezone_confidence: u.timezone_confidence, scheduled_dispatch_at: u.scheduled_dispatch_at ?? null })),
    dispatchErrors: disp ? disp.results.filter((r) => !r.ok) : [], queueUpdateFailed: queueFailed },
} }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final record on every path. Lead IDs, timezones and decisions only; contact
// points are reduced to presence flags. No secrets, no endpoint URLs.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const one = (n) => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
const all = (n) => { try { return $(n).isExecuted ? $(n).all().map((i) => i.json) : []; } catch (e) { return []; } };
const load = one('Load & Normalize Leads') || {};
const route = one('Route & Build Dispatch Batches');
const disp = one('Collect Dispatch Results');
const q = one('Build Queue Updates');
const qw = all('Queue: Update Lead Status');
const sl = all('Slack: Post Summary');
const wh = all('Webhook: Post Summary');

let outcome = 'no_leads';
if (route) {
  if (!route.dispatchCount) outcome = route.counts.defer ? 'all_leads_queued' : 'no_dispatchable_leads';
  else if (cfg.sandboxMode) outcome = 'dispatchable_sandbox';
  else if (!route.dispatchAllowed) outcome = cfg.dryRun ? 'dispatchable_dry_run' : 'dispatchable_dispatch_disabled';
  else if (disp && disp.failed.length) outcome = disp.dispatched.length ? 'dispatched_partially' : 'dispatch_failed';
  else outcome = 'dispatched';
}
const status = (ran, list) => (!ran ? 'not_sent' : list.some((x) => x.error) ? 'failed' : 'sent');
return [{ json: {
  workflow: 'n8n-outbound-lead-time-zone-optimal-dispatch-scheduler',
  runId: cfg.runId, executionMode: cfg.executionMode, finishedAt: new Date().toISOString(), outcome,
  safety: { sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun, dispatchEnabled: cfg.dispatchEnabled, dispatchAllowed: route ? route.dispatchAllowed : false, queueWriteEnabled: cfg.queueWriteEnabled, evaluationTimeOverride: cfg.nowOverride || null },
  window: route ? route.window : null,
  source: load.source || null, webhookAuth: load.auth || null, received: load.received || 0, rejected: load.rejected || [],
  counts: route ? route.counts : null,
  statusCounts: q ? q.statusCounts : null,
  leads: route ? route.leads.map((l) => ({ leadId: l.leadId, hasEmail: Boolean(l.email), hasPhone: Boolean(l.phone), timezone: l.resolvedTimezone, method: l.resolution.method, confidence: l.resolution.confidence, localTime: l.localTime || null, decision: l.decision, reason: l.reason, scheduledDispatchAt: l.scheduledDispatchAt || null })) : [],
  dispatch: disp ? disp.results : [],
  queueUpdate: status(qw.length > 0, qw),
  notifications: { slack: status(sl.length > 0, sl), webhook: status(wh.length > 0, wh) },
} }];
